public class EntityPlayerLocal{public World world;public int entityId=7;public Buffs Buffs=new();public int Adjustments;public bool Suppress;public void AdjustItemsForSandboxOptions(){if(RebirthGearSandboxAdjustmentDeferral.AllowNative(this)&&!Suppress){Adjustments++;RebirthGearSandboxAdjustmentDeferral.NativeCompleted(this,true);}else RebirthGearSandboxAdjustmentDeferral.NativeCompleted(this,false);}public bool Dead;public bool IsSpawned()=>true;public bool IsDead()=>Dead;}
