public static class RebirthGearPreparationClient{public static int Requests,OriginalRequests;public static object LastOriginal;public static bool TryRequestOriginal(EntityPlayerLocal p,object original){OriginalRequests++;LastOriginal=original;return false;}public static bool TryRequestSaved(EntityPlayerLocal p){Requests++;return true;}}
public static class RebirthGearOwnerApplySequence{public enum Result{Applied,Pending}}
public static class RebirthGearOfferClient{public static Offer Offer;public static int Applies,Applied,Rejected,Finishes;public static RebirthGearOwnerApplySequence.Result Result=RebirthGearOwnerApplySequence.Result.Applied;public static bool TryGetCurrentOffer(World w,int id,out Offer o){o=Offer;return o!=null;}public static bool TryFinishCurrentTerminal(World w,int id){Finishes++;return false;}public static bool RequestAppliedConfirmation(World w,int id){Applied++;return true;}public static bool RequestRejectedConfirmation(World w,int id){Rejected++;return true;}public static RebirthGearOwnerApplySequence.Result TryApplyCurrentOffer(World w,int id){Applies++;return Result;}}
