public static class RebirthBackpackLibraryClientViews{public static bool Available=true;public static long Revision;public static int Requests;public static bool TryGetRevision(World w,int id,out long revision){revision=Available?Revision:-1;return Available;}public static bool Request(World w,int id){Requests++;return true;}}
public static class RebirthBackpackLibraryClientOffers{public static long Revision=-1;public static bool TryGetSettledRevision(World w,int id,out long revision){revision=Revision;return Revision>=0;}}
static class Program{
